import { toUint8Array } from '../aes/bytes.mjs';

const SHORT_ESCAPES = new Map([
  [0x09, '\\t'],
  [0x0a, '\\n'],
  [0x0d, '\\r'],
]);

export function pythonBytesRepr(value) {
  const bytes = toUint8Array(value);
  const hasSingleQuote = bytes.includes(0x27);
  const hasDoubleQuote = bytes.includes(0x22);
  const quote = hasSingleQuote && !hasDoubleQuote ? '"' : "'";
  const quoteCode = quote.charCodeAt(0);
  let body = '';

  for (const byte of bytes) {
    if (byte === 0x5c) {
      body += '\\\\';
      continue;
    }

    if (byte === quoteCode) {
      body += `\\${quote}`;
      continue;
    }

    if (SHORT_ESCAPES.has(byte)) {
      body += SHORT_ESCAPES.get(byte);
      continue;
    }

    if (byte >= 0x20 && byte <= 0x7e) {
      body += String.fromCharCode(byte);
      continue;
    }

    body += `\\x${byte.toString(16).padStart(2, '0')}`;
  }

  return `b${quote}${body}${quote}`;
}

