function basename(pathText) {
  const normalized = String(pathText ?? '');
  const unixParts = normalized.split('/');
  const lastUnixPart = unixParts[unixParts.length - 1] || normalized;
  const windowsParts = lastUnixPart.split('\\');
  return windowsParts[windowsParts.length - 1] || 'test13.mjs';
}

function formatUsage(prog) {
  return `usage: ${prog} [-h] --key KEY --data DATA\n`;
}

export function formatHelp(prog) {
  return `${formatUsage(prog)}\noptions:\n  -h, --help   show this help message and exit\n  --key KEY\n  --data DATA\n`;
}

function errorResult(prog, message) {
  return {
    code: 2,
    stream: 'stderr',
    text: `${formatUsage(prog)}${prog}: error: ${message}\n`,
  };
}

function resolveLongOption(name) {
  const known = ['help', 'key', 'data'];

  if (known.includes(name)) {
    return { status: 'ok', name };
  }

  const matches = known.filter((candidate) => candidate.startsWith(name));

  if (matches.length === 1) {
    return { status: 'ok', name: matches[0] };
  }

  if (matches.length > 1) {
    return {
      status: 'ambiguous',
      message: `ambiguous option: --${name} could match ${matches.map((match) => `--${match}`).join(', ')}`,
    };
  }

  return { status: 'unknown', message: `unrecognized arguments: --${name}` };
}

export function parseCommandLine(argv = process.argv) {
  const prog = basename(argv[1] ?? 'test13.mjs');
  const values = { key: undefined, data: undefined };
  const args = argv.slice(2);
  const extras = [];

  for (let index = 0; index < args.length; index += 1) {
    const token = args[index];

    if (token === '--') {
      extras.push(...args.slice(index + 1));
      break;
    }

    if (token === '-h') {
      return { code: 0, stream: 'stdout', text: formatHelp(prog) };
    }

    if (token.startsWith('--')) {
      const equalsIndex = token.indexOf('=');
      const rawName = token.slice(2, equalsIndex === -1 ? undefined : equalsIndex);
      const resolution = resolveLongOption(rawName);

      if (resolution.status === 'ambiguous') {
        return errorResult(prog, resolution.message);
      }

      if (resolution.status === 'unknown') {
        return errorResult(prog, resolution.message);
      }

      const optionName = resolution.name;

      if (optionName === 'help') {
        return { code: 0, stream: 'stdout', text: formatHelp(prog) };
      }

      let optionValue;

      if (equalsIndex !== -1) {
        optionValue = token.slice(equalsIndex + 1);
      } else {
        const next = args[index + 1];

        if (next === undefined || next === '--' || next === '-h' || next.startsWith('--')) {
          return errorResult(prog, `argument --${optionName}: expected one argument`);
        }

        optionValue = next;
        index += 1;
