function xtime(value) {
  return (((value << 1) & 0xff) ^ ((value & 0x80) !== 0 ? 0x1b : 0x00)) & 0xff;
}

function gfMul(left, right) {
  let a = left & 0xff;
  let b = right & 0xff;
  let product = 0;

  while (b !== 0) {
    if ((b & 1) !== 0) {
      product ^= a;
    }

    a = xtime(a);
    b >>>= 1;
  }

  return product & 0xff;
}

function gfPow(base, exponent) {
  let value = base & 0xff;
  let power = exponent;
  let result = 1;

  while (power > 0) {
    if ((power & 1) !== 0) {
      result = gfMul(result, value);
    }

    value = gfMul(value, value);
    power >>>= 1;
  }

  return result & 0xff;
}

function gfInverse(value) {
  if (value === 0) {
    return 0;
  }

  return gfPow(value, 254);
}

function rotlByte(value, shift) {
  return ((value << shift) | (value >>> (8 - shift))) & 0xff;
}

function buildSBoxes() {
  const sbox = new Uint8Array(256);
  const inverse = new Uint8Array(256);

  for (let index = 0; index < 256; index += 1) {
    const inverted = gfInverse(index);
    const mapped =
      inverted ^
      rotlByte(inverted, 1) ^
      rotlByte(inverted, 2) ^
      rotlByte(inverted, 3) ^
      rotlByte(inverted, 4) ^
      0x63;

    sbox[index] = mapped & 0xff;
    inverse[sbox[index]] = index;
  }

  return { sbox, inverse };
}

function buildRcon() {
  const rcon = new Uint8Array(16);
  rcon[1] = 0x01;

  for (let index = 2; index < rcon.length; index += 1) {
    rcon[index] = xtime(rcon[index - 1]);
  }

  return rcon;
}

const { sbox: SBOX, inverse: INV_SBOX } = buildSBoxes();
const RCON = buildRcon();

export { INV_SBOX, RCON, SBOX, gfMul };

